mapper.select:
select * from (
    SELECT mp.*,mi.MACHINE_NAME
    FROM T_TM_MOUTH_PLATE mp
    LEFT JOIN T_TM_MACHINE_INFO mi
    ON mp.MACHINE_ID = mi.ID
    where mp.del_flag = '0'
    and INSTR(mp.mouth_plate_code, #{mouthPlateCode}) > 0
    and mp.machine_id = #{machineId}
    and mp.status = #{status}
    order by mp.create_time desc
) t
order by ${orderStr}

SELECT count(1)
FROM T_TM_MOUTH_PLATE mp
LEFT JOIN T_TM_MACHINE_INFO mi
ON mp.MACHINE_ID = mi.ID
where mp.del_flag = '0'
and mp.mouth_plate_code = #{mouthPlateCode}
and mp.machine_id = #{machineId}
and mp.id != #{id}

select * FROM T_TM_MOUTH_PLATE
where del_flag = '0'
and id != #{id}
and machine_id is null
and machine_id = #{machineId}
and mouth_plate_code is null
and mouth_plate_code = #{mouthPlateCode}
